TLM.f("Tempora/Quadp3-4",{"officium":"Feria V post Cineres","rule":["no Gloria","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;","Super populum"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp3-0","from":{"GradualeF":"Tempora/Quadp3-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 54:17-23"},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam ab his, qui appropínquant mihi, et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet."},{"k":"ref","la":"Ps 54:2-3"},{"k":"text","la":"Exáudi, Deus, oratiónem meam, et ne despéxeris deprecatiónem meam: inténde mihi et exáudi me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam ab his, qui appropínquant mihi, et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet."}],"Oratio":[{"k":"text","la":"Deus, qui culpa offénderis, pæniténtia placáris: preces pópuli tui supplicántis propítius réspice; et flagélla tuæ iracúndiæ, quæ pro peccátis nostris merémur, avérte."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ."},{"k":"ref","la":"Is 38:1-6"},{"k":"text","la":"In diébus illis: Ægrotávit Ezechías usque ad mortem: et introívit ad eum Isaías fílius Amos Prophéta, et dixit ei: Hæc dicit Dóminus: Dispóne dómui tuæ, quia moriéris tu, et non vives. Et convértit Ezechías fáciem suam ad paríetem, et orávit ad Dóminum, et dixit: Obsecro, Dómine, meménto, quæso, quómodo ambuláverim coram te in veritáte et in corde perfécto, et, quod bonum est in óculis tuis, fécerim. Et flevit Ezechías fletu magno. Et factum est verbum Dómini ad Isaíam, dicens: Vade, et dic Ezechíæ: Hæc dicit Dóminus, Deus David patris tui: Audívi oratiónem tuam, et vidi lácrimas tuas: ecce, ego adjíciam super dies tuos quíndecim annos: et de manu regis Assyriórum éruam te et civitátem istam, et prótegam eam, ait Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 54:23, 17, 18 et 19"},{"k":"text","la":"Jacta cogitátum tuum in Dómino, et ipse te enútriet."},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam ab his, qui appropínquant mihi.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 8:5-13"},{"k":"text","la":"In illo témpore: Cum introísset Jesus Caphárnaum, accéssit ad eum centúrio, rogans eum, et dicens: Dómine, puer meus jacet in domo paralýticus, et male torquétur. Et ait illi Jesus: Ego véniam et curábo eum. Et respóndens centúrio, ait: Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur puer meus. Nam et ego homo sum sub potestáte constitútus, habens sub me mílites, et dico huic: Vade, et vadit; et alii: Veni, et venit; et servo meo: Fac hoc, et facit. Audiens autem Jesus, mirátus est, et sequéntibus se dixit: Amen, dico vobis, non invéni tantam fidem in Israël. Dico autem vobis, quod multi ab Oriénte et Occidénte vénient, et recúmbent cum Abraham et Isaac et Jacob in regno cœlórum: fílii autem regni ejiciéntur in ténebras exterióres: ibi erit fletus et stridor déntium. Et dixit Jesus centurióni: Vade, et, sicut credidísti, fiat tibi. Et sanátus est puer in illa hora."}],"Offertorium":[{"k":"ref","la":"Ps 24:1-3"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"Secreta":[{"k":"text","la":"Sacrifíciis præséntibus, Dómine, quǽsumus, inténde placátus: ut et devotióni nostræ profíciant et salúti."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 50:21"},{"k":"text","la":"Acceptábis sacrifícium justítiæ, oblatiónes et holocáusta, super altáre tuum, Dómine."}],"Postcommunio":[{"k":"text","la":"Cœléstis doni benedictióne percépta: súpplices te, Deus omnípotens, deprecámur; ut hoc idem nobis et sacraménti causa sit et salútis."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Parce, Dómine, parce populo tuo: ut, dignis flagellatiónibus castigátus, in tua miseratióne respíret."},{"k":"macro","name":"Per Dominum"}]},"hr":{"904d7e91b9e07e5e":{"t":"Ps 54, 17 i 19 i 20 i 23\n(Ps 54, 17 i 19 i 20 i 23) Dok sam zazivao Gospodina, uslišio je moj glas protiv onih koji mi se približuju. Ponizio ih je on koji je prije vjekova i ostaje u vijeke. Baci na Gospodina svoju brigu i on će te ishraniti. (Ps 54, 2-3) Usliši, Bože, molitvu moju i ne prezri prošnju moju, pogledaj na me i usliši me.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 54, 17 i 19 i 20 i 23) Dok sam zazivao Gospodina, uslišio je moj glas protiv onih koji mi se približuju. Ponizio ih je on koji je prije vjekova i ostaje u vijeke. Baci na Gospodina svoju brigu i on će te ishraniti.","kn":"(Ps. 54, 17-23). Kad sam vapio ka Gospodinu, uslišao je glas moj i oelobodio me od onih, koji mi se približivahu i ponizio ih je onaj, koji je prije vjekova i ostaje u vijeke; Gospodinu prepusti brige svoje i on će te obraniti. (Pš. 54, ' 2) Usiiši, Bože, molitvu moju, i ne prezri prošnje moje, pazđ ma me i saslušaj me. Slava Ocu . . . Kad sam...","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"98916f3983f62340":{"t":"<i>Pomolimo se</i>.\nBože, koga grijeh vrijeđa a pokora ublažuje, pogledaj milostivo ponizne molbe puka svoga i odvrati bičeve srdžbe svoje koje za grijehe svoje zaslužujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koga grijeh vrijeđa, a pokora ublažuje, pogledaj milostivo ponizne molbe puka svojega i odvrati bičeve srdžbe svoje, koje za grijehe svoje zaslužujemo.","knRef":"Kniewald 1942, str. 918–919 (snimka 460) (OCR)"},"c49d39e6fae8b518":{"t":"Iz 38, 1-6\nČitanje Izaije proroka. U one dane Ezekija se razboli na smrt, i k njemu dođe Amosov sin prorok Izaija i reče mu: Gospodin ti kaže da urediš svoje račune, jer ćeš umrijeti i nećeš živjeti. Ezekija se okrene k zidu, pomoli se Gospodinu i reče: Molim te, Gospodine, sjeti se da sam ti bio vjeran i živio čista srca i da sam pred tobom činio što je dobro. I udari Ezekija u gorki plač. Tada dođe Gospodin i zapovjedi Izaiji: Idi i reci Ezekiji: Ovo govori Gospodin Bog tvojeg oca Davida: Čuo sam tvoju molitvu i vidio tvoje suze. Evo, dat ću tvom životu petnaest godina i izbavit ću tebe i ovaj grad iz ruku asirskoga kralja i ja ću ga obraniti, govori Gospodin svemogući.","kn":"Čitanje Izaije Proroka (Iz. 38, 1-6). U one dane; Razboli se Ezekija na smrt; i dođe njemu Izaija, sin Amosov, prorok, ,i reče mu; Ovo govori Gospodin; uredi svoje kućne stvari, jer ćeš umrijeti, i ne ćeš živjeti. A Ezekija se okrenu licem k zidu, i pomoli se Gospodinu, 1 reče; Molim, Gospodine, spomeni se, da sam hodio pred Tobom vjerno i s čistim srcem, i da sam činio, što je dobro pred očima Tvojim. I udari Ezekija u plač veliki. Tada dođe riječ Gospodnja Izaiji govoreći; i reci Ezekiji; Ovo govori Gospodm Bog Davidia, oca tvojega; Ct* molitvu tvoju, i vidjeh suze tvoje; evo dodat ću tvome vijeku petnaest godina; i izbavit ću iz^ ruku kralja Asirskoga tebe i ovaj grad,, i branit ću ga, govori Gospodin svemogući.","knRef":"Kniewald 1942, str. 102–103 (snimka 52) (OCR)"},"66177f8c11745c60":{"t":"Ps 54, 23 i 17 i 18 i 19\nPrebaci na Gospodina svoju brigu i on će te hraniti. Kad sam zazvao Gospodina, uslišio je moj glas protiv onih koji mi se neprijateljski približuju.","kn":"(Ps. 54, 23, 17, 18, 19). Prepusti Gospodinu brige s.voje i on će te uzdržati. Kad sam vapio Gospodinu, uslišao je glas moj od onih, koji mi se približavahu.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"b8e944654ac9d2b4":{"t":"Mt 8, 5-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: kad je Isus ušao u Kafarnaum pristupi k njemu stotnik, zamoli ga i reče: Gospodine, moj sluga leži kod kuće uzet i teško se muči. Isus mu reče: Ja ću doći i izliječit ću ga. A stotnik odgovori: Gospodine, nisam dostojan da uđeš pod krov moj, nego samo reci riječ i ozdravit će moj sluga. I ja sam čovjek pod vlašću i imam pod sobom vojnike, pa kažem jednomu: Idi, – i on ide, i drugome: Dođi, – i on dođe, a svojem sluzi: Učini to, – i on učini. Kad je Isus to čuo, zadivi se i reče pratiocima: Zaista vam kažem u Izraelu nisam našao tolike vjere. Kažem vam da će doći mnogi s istoka i sa zapada i sjest će s Abrahamom, Izakom i Jakovom za stol u nebeskom kraljevstvu, a sinovi će kraljevstva biti izbačeni napolje u tamu, gdje će biti plač i škripa zubi. A stotniku reče: Idi i neka ti bude kako si vjerovao. I u taj čas ozdravi sluga."},"314b0585b7d97b62":{"t":"Ps 24, 1-3\nK tebi, Gospodine, uzdižem svoju dušu, Bože moj, u tebe se uzdam, ne daj da se postidim. Neka mi se ne rugaju neprijatelji, jer se neće smesti nitko od onih koji tebe čekaju.","kn":"(Ps. 24, 1-3). K Tebi, Gospodine, dižem dušu svoju; Bože moj, u Tebe se ufam, ne daj, da se zastidim i da mi se podsmijevaju neprijatelji moji, jer, koji Te čekaju, ne će se zastidjeti. r","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"90a1614471aa68a1":{"t":"Umilostivljen pogledaj, molimo, Gospodine, na ove žrtve, da koriste i našoj pobožnosti i spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, molimo Te, milostivo na ove žrtve i podaj, da koriste i našoj pobožnosti i spasenju, po G. n.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"b318615739a9dfeb":{"t":"Ps 50, 21\nPrimat ćeš prave žrtve, prinose i paljenice na oltar svoj, Gospodine.","kn":"(Ps. 50, 21). Primit ćeš žrtvu pravde, prinose i paljenice na žrtveniku svojem, Gospoaine.","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"3f5aa8b2806196b8":{"t":"<i>Pomolimo se</i>.\nPošto smo primili blagoslov nebeskog dara ponizno te molimo, svemogući Bože, da nam ovo bude sredstvo otajstva i spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši blagoslov nebeskoga dara ponizno Te molimo, svemogući Bože, da nam ovaj dar bude uzrokom i tajne i spasenja, po G. n.","knRef":"Kniewald 1942, str. 204–205 (snimka 103) (OCR)"},"22a92bf3eb6efc07":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nSmiluj se, Gospodine, smiluj se narodu svome, da kažnjen zasluženim bičevima odahne u tvom milosrđu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! 'Prignite ponizno glave pred Bogom! Oprosti, Go^odine, oprosti puku svomu, da bijen zasluženim bičevima: u Tvojoj milosrdnosti odahne, po G. in.' I. K. • '","knRef":"Kniewald 1942, str. 104–105 (snimka 53) (OCR)"}}});
